#!/usr/bin/env python3
"""Render generated records through the unmodified learning UI without a database."""
import argparse
import hashlib
import http.server
import json
import mimetypes
import os
from pathlib import Path
import re
import shutil
import subprocess
import threading
from urllib.parse import parse_qs, unquote, urlparse

REPO = Path(__file__).resolve().parents[2]

# Use the installed browser driver; do not install a second rendering stack.
BROWSER_SCRIPT = r"""
const fs = require('fs');
const config = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const { chromium } = require(config.playwright);
(async () => {
  const browser = await chromium.launch({headless:true, executablePath:config.browser,
    args:['--disable-dev-shm-usage']});
  const reports = [];
  try {
    for (let index = 0; index < config.count; index++) {
      const context = await browser.newContext({viewport:{width:1280,height:1000},deviceScaleFactor:1});
      const page = await context.newPage();
      const errors = [];
      page.on('pageerror', error => errors.push(String(error)));
      await page.route('**/*', route => new URL(route.request().url()).origin === config.origin
        ? route.continue() : route.abort());
      await page.goto(config.origin + '/learn?activityId=' + index, {waitUntil:'networkidle'});
      await page.locator('.lesson-content').waitFor();
      // Lazy images in the worked solution also need to load before a full-page capture.
      await page.evaluate(async () => {
        for (const image of document.images) image.loading = 'eager';
        if (window.MathJax?.startup?.promise) await MathJax.startup.promise;
        await document.fonts.ready;
      });
      await page.waitForLoadState('networkidle');
      await page.evaluate(async () => {
        if (window.MathJax?.typesetPromise) await MathJax.typesetPromise();
        await document.fonts.ready;
        await Promise.all([...document.images].map(image => image.decode().catch(() => {})));
        await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
      });
      const state = await page.evaluate(() => ({
        mathContainers:document.querySelectorAll('mjx-container').length,
        mathErrors:[...document.querySelectorAll('[data-mml-node="merror"],mjx-merror,.math-error')].map(node=>node.textContent),
        brokenImages:[...document.images].filter(image=>!image.complete || !image.naturalWidth).map(image=>image.src),
        danglingGlyphs:[...document.querySelectorAll('mjx-container use')].map(node=>node.getAttribute('href') || node.getAttribute('xlink:href'))
          .filter(href=>href?.startsWith('#') && !document.getElementById(href.slice(1))),
        text:document.querySelector('.lesson-content').innerText,
        fonts:document.fonts.status
      }));
      const stem = config.output + '/question-' + String(index + 1).padStart(3,'0');
      await page.screenshot({path:stem+'.png',fullPage:true,animations:'disabled'});
      fs.writeFileSync(stem+'.html',await page.content());
      state.index=index; state.screenshot=stem+'.png'; state.javascriptErrors=errors;
      state.passed=!errors.length && !state.mathErrors.length && !state.brokenImages.length
        && !state.danglingGlyphs.length && state.fonts==='loaded'
        && (!config.expectedMath[index] || state.mathContainers>0);
      reports.push(state);
      await context.close();
    }
  } finally { await browser.close(); }
  const report={renderer:'unmodified ui/Learning.html and learning.js',database_writes:0,
    passed:reports.every(item=>item.passed),cases:reports};
  fs.writeFileSync(config.output+'/rendering.json',JSON.stringify(report,null,2)+'\n');
  console.log(JSON.stringify({passed:report.passed,count:reports.length,report:config.output+'/rendering.json'}));
  if (!report.passed) process.exitCode=1;
})().catch(error=>{console.error(error);process.exitCode=1});
"""


def enum(value):
    return str(value[":db/ident"] if isinstance(value, dict) else value).split("/")[-1]


def answer_id(value):
    if isinstance(value, dict):
        return str(value[":answer/id"])
    if isinstance(value, (list, tuple)) and len(value) == 2 and value[0] == ":answer/id":
        return str(value[1])
    return str(value)


def preview(record, index):
    question = record.get("question", record)
    fields = []
    for number, field in enumerate(question[":question/answer-fields"]):
        choices = [{"id": str(answer[":answer/id"]), "type": enum(answer[":answer/type"]),
                    "value": answer[":answer/value"], "feedback": answer.get(":answer/feedback", "")}
                   for answer in field[":answer-field/choices"]]
        correct_id = answer_id(field[":answer-field/correct"])
        correct = next(answer for answer in choices if answer["id"] == correct_id)
        kind = enum(field[":answer-field/type"])
        fields.append({"id": field.get(":answer-field/id", number), "key": field[":answer-field/key"],
                       "type": kind, "answerType": correct["type"], "choices": choices,
                       "correctAnswer": correct, "response": {"value": correct["value"], "choiceId": correct_id}})
    step = {"kind": "question", "contentId": index + 1, "status": "correct", "problem": question[":question/problem"],
            "solution": question.get(":question/worked-solution", ""), "fields": fields}
    return {"activityId": str(index), "title": "Generator review", "type": "lesson", "steps": [step],
            "courseId": "review", "learner": {"id": 1, "name": "Offline review"}}


def resolve_node(playwright, node=None, environment=None):
    """Prefer Playwright's installed runtime over an incompatible system Node."""
    environment = os.environ if environment is None else environment
    explicit = node or environment.get('COURSE_ACADEMY_NODE_EXECUTABLE')
    candidates = [explicit] if explicit else [
        Path(playwright).parent.parent / 'bin/node',
        Path.home() / '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/bin/node',
        shutil.which('node', path=environment.get('PATH')),
    ]
    checked, failures = set(), []
    for candidate in candidates:
        if not candidate:
            continue
        executable = shutil.which(str(candidate), path=environment.get('PATH'))
        if not executable or executable in checked:
            continue
        checked.add(executable)
        try:
            result = subprocess.run([executable, '--version'], capture_output=True,
                                    text=True, check=True, timeout=5)
            version = re.fullmatch(r'v(\d+)\.\d+\.\d+\s*', result.stdout)
            if version and int(version[1]) >= 20:
                return executable
            failures.append(f'{executable}: {result.stdout.strip()}')
        except (OSError, subprocess.SubprocessError) as error:
            failures.append(f'{executable}: {error}')
    raise RuntimeError('Playwright requires Node >=20. Set --node or '
                       'COURSE_ACADEMY_NODE_EXECUTABLE to an installed compatible runtime. '
                       + '; '.join(failures))


#!/usr/bin/env python3
"""Audit publication filtering against saved inventory without a database connection."""
import argparse
import hashlib
import json
from pathlib import Path
import sys
from urllib.parse import unquote, urlsplit

REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO))
from scripts.generator_publish import ImageLibrary, enum, localize_record, prepare_records


class AuditImages(ImageLibrary):
    """Read canonical images in place; store all localized bytes under evidence."""
    def __init__(self, output_root, asset_root, canonical_root):
        super().__init__(output_root, asset_root)
        self.canonical_root = Path(canonical_root).resolve()

    def resolve(self, source):
        reference = source.strip().strip('<>')
        mapped = self.mapping.get(reference, reference)
        parsed = urlsplit(mapped)
        relative = Path(unquote(parsed.path))
        if not parsed.scheme and relative.parts[:1] == ('images',):
            candidate = (self.canonical_root / relative).resolve()
            if candidate.is_relative_to(self.canonical_root) and candidate.is_file():
                data = candidate.read_bytes()
                expected = self.expected_hashes.get(mapped)
                if expected and hashlib.sha256(data).hexdigest() != expected:
                    raise ValueError('Captured image differs from its source manifest: ' + source)
                return self.store(data, source)
        return super().resolve(source)


def audit(records, inventory, source, difficulty, output, asset_root, math_root):
    output, math_root = Path(output).resolve(), Path(math_root).resolve()
    if output.is_relative_to(math_root):
        raise ValueError('Audit output must be outside the published math root')
    if not isinstance(records, list):
        raise ValueError('Input must be a JSON array of generated records')
    for key in ('database', 'lineage', 'kp_id'):
        if inventory.get(key) != source[key]:
            raise ValueError('Inventory/source mismatch: ' + key)
    if any(enum(r['question'].get(':question/difficulty')) != ':question.difficulty/' + difficulty for r in records):
        raise ValueError('Input contains a record outside the requested difficulty; the runner rejects this batch')
    kp_uuid = source['material']['kp'][':knowledge-point/id']
    staged = output / 'assets'

    def localize(record, _math_root, _asset_root):
        return localize_record(record, staged, asset_root,
                               library=AuditImages(staged, asset_root, math_root))

    accepted, duplicates = prepare_records(records, source['kp_id'], kp_uuid,
        inventory['fingerprints'], staged, asset_root, localizer=localize)
    output.mkdir(parents=True, exist_ok=True)
    (output / 'accepted.json').write_text(json.dumps(accepted, indent=2, ensure_ascii=False) + '\n')
    report = {
        'database_writes': 0, 'inventory_basis': inventory['basis'],
        'kp_id': source['kp_id'], 'difficulty': difficulty,
        'input_count': len(records), 'duplicate_count': duplicates, 'accepted_count': len(accepted),
        'accepted_file': 'accepted.json', 'asset_root': 'assets',
        'stages_examined': ['requested difficulty', 'knowledge-point identity', 'image localization',
                            'question validation', 'stable identities', 'inventory and batch deduplication'],
        'limits': ['Uses captured inventory; concurrent publication may change duplicates.',
                   'Does not examine generator rejection/resampling or certify mathematical or pedagogical correctness.',
                   'Does not simulate learner history, weighted selection, database identity collisions, or publication.'],
    }
    (output / 'delivery.json').write_text(json.dumps(report, indent=2) + '\n')
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ('input', 'inventory', 'source', 'output'):
        parser.add_argument('--' + name, type=Path, required=True)
    parser.add_argument('--difficulty', choices=('easy', 'moderate', 'hard'), required=True)
    parser.add_argument('--asset-root', type=Path, help='Generated asset directory; defaults to input parent')
    parser.add_argument('--math-root', type=Path, default=Path('/media/jake/SSD/EDB/math'))
    args = parser.parse_args()
    paths = {'input': args.input, 'inventory': args.inventory, 'source': args.source}
    data = {name: json.loads(path.read_text()) for name, path in paths.items()}
    report = audit(data['input'], data['inventory'], data['source'], args.difficulty,
                   args.output, args.asset_root or args.input.resolve().parent, args.math_root)
    report['input_sha256'] = {name: hashlib.sha256(path.read_bytes()).hexdigest() for name, path in paths.items()}
    report['implementation_sha256'] = {str(path.relative_to(REPO)): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in (Path(__file__), REPO / 'scripts/generator_publish.py', REPO / 'capture/scripts/database/images.py')}
    (args.output / 'delivery.json').write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps({key: report[key] for key in ('input_count', 'duplicate_count', 'accepted_count', 'inventory_basis')}
                     | {'report': str(args.output / 'delivery.json')}))


if __name__ == '__main__':
    main()
